function buildProguardBridgeRules(packageName, existingRules) {
  const rules = [];
  if (!existingRules.includes("NativeBillingBridge")) {
    rules.push(`-keep class ${packageName}.NativeBillingBridge { *; }`);
  }
  if (!existingRules.includes("NativeVibrationBridge")) {
    rules.push(`-keep class ${packageName}.NativeVibrationBridge { *; }`);
  }
  if (!existingRules.includes("NativeTextToSpeechBridge")) {
    rules.push(`-keep class ${packageName}.NativeTextToSpeechBridge { *; }`);
  }
  if (!existingRules.includes("@android.webkit.JavascriptInterface")) {
    rules.push(`-keepclassmembers class * {
    @android.webkit.JavascriptInterface <methods>;
}`);
  }
  if (rules.length === 0) return "";
  return `
# The remote WebView calls these methods by JavaScript interface name.
${rules.join("\n")}
`;
}

async function patchJavaTemplates(projectDir, packageName) {
  const packagePath = packageName.split(".").join(path.sep);
  const javaDir = path.join(projectDir, "app", "src", "main", "java", packagePath);
  for (const templateName of ANDROID_JAVA_TEMPLATE_FILES) {
    const template = await readText(path.join(TEMPLATE_DIR, templateName));
    await writeText(
      path.join(javaDir, templateName),
      template.replaceAll("__PACKAGE__", packageName),
    );
  }
}

async function copyOfflineShellAssets(projectDir) {
  const destination = path.join(projectDir, "app", "src", "main", "assets", "foxiesdeck-offline");
  await fs.mkdir(destination, { recursive: true });
  await fs.cp(OFFLINE_SHELL_SOURCE, destination, { recursive: true, force: true });

  for (const requiredFile of ["index.html", "offline-shell.js", "card-renderer.js", "card-design.css", "super-water.ttf"]) {
    const source = await fs.readFile(path.join(OFFLINE_SHELL_SOURCE, requiredFile));
    const packaged = await fs.readFile(path.join(destination, requiredFile));
    if (!source.equals(packaged)) {
      throw new Error(`The packaged offline shell is stale or incomplete: ${requiredFile}`);
    }
  }
}

async function patchLauncherColors(projectDir) {
  const colorsPath = path.join(projectDir, "app", "src", "main", "res", "values", "colors.xml");
  let colors;
  try {
    colors = await readText(colorsPath);
  } catch {
    colors = "<resources>\n</resources>\n";
  }

  const launcherColor = `    <color name="ic_launcher_background">${LAUNCHER_COLOR}</color>`;
  if (colors.includes('name="ic_launcher_background"')) {
    colors = colors.replace(
      /\s*<color name="ic_launcher_background">[^<]*<\/color>/,
      `\n${launcherColor}`,
    );
  } else {
    colors = colors.replace("</resources>", `${launcherColor}\n</resources>`);
  }
  await writeText(colorsPath, colors);
}

async function copyNativeSplashAsset(projectDir) {
  const targetPath = path.join(
    projectDir,
    "app",
    "src",
    "main",
    "res",
    "drawable-nodpi",
    "native_splash.png",
  );
  await fs.mkdir(path.dirname(targetPath), { recursive: true });
  await fs.copyFile(NATIVE_SPLASH_SOURCE, targetPath);
}

function loadVocabularyCardsForNativeFallback() {
  const bundle = buildSync({
    absWorkingDir: ROOT,
    bundle: true,
    entryPoints: [path.join(ROOT, "src", "data", "cards.ts")],
    format: "cjs",
    logLevel: "silent",
    platform: "node",
    target: "node20",
    tsconfig: path.join(ROOT, "tsconfig.json"),
    write: false,
  });
  const module = { exports: {} };
  runInNewContext(bundle.outputFiles[0].text, {
    Buffer,
    clearTimeout,
    console,
    exports: module.exports,
    module,
    process,
    require,
    setTimeout,
  });
  return module.exports.VOCABULARY_CARDS;
}

function javaString(value) {
  return JSON.stringify(String(value ?? ""));
}

